/* Approach: a quiet process-sheet surface, with the selected diagram in focus. */
.page-hero-approach {
  position: relative;
  isolation: isolate;
  background: #f3eff8;
  overflow: hidden;
}
.page-hero-approach::before {
  content: "";
  position: absolute;
  inset: 0 0 0 43%;
  z-index: -1;
  background: #fff;
  border-radius: 140px 0 0 0;
}
.page-hero-approach .workflow-hero > a {
  padding: 0;
}
.workflow-selector {
  gap: 12px;
  padding-block: 24px 40px;
}
.workflow-card {
  --stage-accent: #481e72;
  --stage-paper: #f0eaf8;
  min-height: 232px;
  padding: 24px 18px 18px;
  gap: 12px;
  border: 1px solid #d7cce5;
  border-radius: 12px;
  background: #fff;
  overflow: hidden;
  transition:
    background-color 180ms ease,
    border-color 180ms ease;
}
.workflow-card:nth-child(2) {
  --stage-accent: #227e7b;
  --stage-paper: #eaf5f3;
}
.workflow-card:nth-child(3) {
  --stage-accent: #664b8b;
  --stage-paper: #eeeaf6;
}
.workflow-card:nth-child(4) {
  --stage-accent: #356d83;
  --stage-paper: #eaf2f6;
}
.workflow-card:nth-child(5) {
  --stage-accent: #516846;
  --stage-paper: #eff3e9;
}
.workflow-card::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 32px;
  height: 32px;
  background: var(--stage-paper);
  clip-path: polygon(0 0, 100% 100%, 100% 0);
}
.workflow-card .workflow-step {
  position: absolute;
  top: 18px;
  right: 20px;
  font:
    700 32px/1 Nunito,
    sans-serif;
  color: var(--stage-accent);
}
.workflow-card > img {
  width: 64px;
  height: 64px;
  margin-block: 8px 12px;
}
.workflow-card strong {
  font:
    700 23px/1.2 Nunito,
    sans-serif;
  color: var(--stage-accent);
}
.workflow-card > span:last-child {
  max-width: 20ch;
  color: #554766;
}
.workflow-card:hover {
  background: var(--stage-paper);
  border-color: var(--stage-accent);
}
.workflow-card[aria-pressed="true"] {
  background: var(--stage-paper);
  border-color: var(--stage-accent);
  box-shadow: none;
  outline: 2px solid var(--stage-accent);
  outline-offset: -3px;
}
.workflow-card:focus-visible {
  outline: 3px solid #481e72;
  outline-offset: 4px;
}
.practice-detail .profile-principles {
  background: #f3eff8;
}
.practice-detail .profile-principles::before {
  display: none;
}
.practice-detail .profile-principles :is(h2, h3) em {
  color: inherit;
}
.practice-detail .profile-principles .practice-icon img {
  filter: grayscale(1);
}
