}
.story-backdrop {
  position: relative;
  z-index: 1000;
  height: 210px;
  padding: 54px 48px;
  box-sizing: border-box;
  background: #351953;
  background-size: cover;
  background-position: center;
  border-radius: 24px 24px 0 0;
