/* Desktop dimensions follow the approved 793 × 1983 composition. Mobile uses
   readable type and controls, rather than shrinking the desktop composition. */
:root {
  font-size: min(calc(var(--final-viewport, 100vw) / 793), 2px);
  --ink: #321068;
  --paper: #fcfbf8;
  --muted: #6255a3;
  --purple: #401078;
  --line: #ded9e9;
  --font-body: Lato, Arial, sans-serif;
  --navy-accent: #401078;
