}
::selection {
  background: #e5d5f4;
  color: #321068;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
textarea {
  font: inherit;
}
button,
a,
summary {
  touch-action: manipulation;
}
button,
summary {
  cursor: pointer;
}
input,
textarea {
  caret-color: var(--purple);
}
:focus-visible {
  outline: 2rem solid #148c99;
  outline-offset: 4rem;
}
h1,
h2,
h3,
p,
figure {
  margin: 0;
}
h1,
h2,
h3 {
