  line-height: 1.42;
}
.final-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 10rem;
  min-height: 30rem;
  padding: 7rem 16rem;
  white-space: nowrap;
  border: 1rem solid #491a78;
  border-radius: 2rem;
  background: linear-gradient(110deg, #43117d, #35106a);
  color: white;
  font: 400 10rem/1.3 var(--font-body);
  box-shadow: 0 3rem 7rem #33105c18;
  transition:
    background 0.18s,
    box-shadow 0.18s;
}
.final-button:hover {
  background: #55208a;
  box-shadow: 0 4rem 10rem #33105c25;
}
.final-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.final-button span,
.text-link span,
.service-arrow {
  font:
    16rem/1 Arial,
    sans-serif;
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 9rem;
  font-size: 9rem;
  font-weight: 600;
  min-height: 30rem;
}
