  position: fixed;
  top: -100px;
  left: 16px;
  z-index: 20;
  background: white;
  padding: 12px;
  font-size: 16px;
}
.final-skip:focus {
  top: 12px;
}
/* Refreshed artwork preserves the approved atlas coordinates. Page text,
