/* Desktop dimensions follow the approved 793 × 1983 composition. Mobile uses
   readable type and controls, rather than shrinking the desktop composition. */
:root {
  font-size: min(calc(var(--final-viewport, 100vw) / 793), 2px);
  --ink: #321068;
  --paper: #fcfbf8;
  --muted: #6255a3;
  --purple: #401078;
  --line: #ded9e9;
  --font-body: Lato, Arial, sans-serif;
  --navy-accent: #401078;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: 20rem;
  scrollbar-color: #aa94cf #fcfbf8;
}
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 12rem/1.4 var(--font-body);
}
::selection {
  background: #e5d5f4;
  color: #321068;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
textarea {
  font: inherit;
}
button,
a,
summary {
  touch-action: manipulation;
}
button,
summary {
  cursor: pointer;
}
input,
textarea {
  caret-color: var(--purple);
}
:focus-visible {
  outline: 2rem solid #148c99;
