    border-radius: 16px 16px 0 0;
    font-size: 24px;
  }
  .story-panel {
    border-radius: 16px 16px 0 0;
    box-shadow: 0 -5px 16px rgba(49, 22, 83, 0.06);
  }
  .client-site .detail-page .story-panel > section {
    padding-block: 24px;
  }
  .story-panel > section:not(.svc-wrap):not(.final-wrap) {
    padding-inline: 8px;
  }
  @supports (position: sticky) {
    .story-stack[data-story-enhanced="true"] .story-panel {
      min-height: min(58svh, 500px);
    }
  }
}
@supports (position: sticky) {
  .story-stack[data-story-enhanced="true"] .story-panel:last-child {
    position: relative;
    top: auto;
    min-height: 0;
  }
}
@media (prefers-reduced-motion: reduce), print {
  .story-stack[data-story-enhanced="true"] :is(.story-backdrop, .story-panel) {
    position: relative;
    top: auto;
    min-height: 0;
  }
}
html[data-motion="off"]
  .story-stack[data-story-enhanced="true"]
  :is(.story-backdrop, .story-panel) {
  position: relative;
  top: auto;
  min-height: 0;
}
/* Approach's chapter backdrop uses abstract curves instead of the hero diagram. */
.detail-page:has(.page-hero-approach) .story-backdrop {
  background-image:
    radial-gradient(
      ellipse at 100% 120%,
      transparent 44%,
      rgba(226, 239, 234, 0.18) 44.2%,
      rgba(226, 239, 234, 0.18) 44.6%,
      transparent 44.8%
    ),
    radial-gradient(
      ellipse at 95% 110%,
      #227e7b 0%,
      #227e7b 30%,
      transparent 30.3%
    ),
    linear-gradient(115deg, #351953 10%, #51346f 72%, #68527e);
}

/* Homepage desktop refinements — 2026-09-30. */
@media (min-width: 901px) {
  main:not(.detail-page) :is(.problem-section, .contact-section) {
    position: relative;
    isolation: isolate;
  }
  main:not(.detail-page) :is(.problem-section, .contact-section)::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background: url("/site-assets/advisory/icons/pathways-flows.svg") no-repeat 3% 65% / auto 75%;
    opacity: 0.09;
  }
  main:not(.detail-page) .contact-section::before {
    background-image: url("/site-assets/advisory/icons/governance.svg");
    background-position: 4% 55%;
    background-size: auto 84%;
    opacity: 0.08;
  }
  main:not(.detail-page) .brief-copy {
    grid-column: 1;
    grid-row: 1;
  }
  main:not(.detail-page) .brief-art {
    grid-column: 2;
    grid-row: 1;
  }
}
@media (min-width: 901px) and (prefers-reduced-motion: no-preference) {
  html:not([data-motion="off"]) main:not(.detail-page) .approach-stages li:is(:hover, :focus-within) .stage-icon {
    animation: home-icon-nod 650ms cubic-bezier(0.23, 1, 0.32, 1) 30ms both;
  }
  @keyframes home-icon-nod {
    0% { transform: translateY(0) rotate(0); }
    40% { transform: translateY(-6px) rotate(-5deg) scale(1.06); }
    70% { transform: translateY(-4px) rotate(3deg) scale(1.04); }
    100% { transform: translateY(-4px) rotate(0) scale(1.04); }
  }
}


